CREATE TABLE insight (
    run_id INTEGER NOT NULL REFERENCES checkpoint_run(id), cluster_key TEXT NOT NULL REFERENCES cluster(key),
    title TEXT NOT NULL, statement TEXT NOT NULL, need_type TEXT NOT NULL, quality_issue INTEGER NOT NULL,
    product_decision INTEGER NOT NULL, category TEXT, aspect TEXT, payload_json TEXT, embedding BLOB,
    PRIMARY KEY (run_id, cluster_key)
);
CREATE TABLE def_requirement (
    id INTEGER PRIMARY KEY, key TEXT NOT NULL, version INTEGER NOT NULL, run_id INTEGER NOT NULL REFERENCES checkpoint_run(id),
    parent_id INTEGER REFERENCES def_requirement(id), area_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'proposed',
    title TEXT NOT NULL, statement TEXT, domain TEXT, aspects_json TEXT, zones_json TEXT, lines_json TEXT, markets_json TEXT,
    targets_json TEXT, decision_type TEXT, today_status TEXT, horizon TEXT, horizon_year INTEGER, kano TEXT,
    evidence_ids_json TEXT, trend_ids_json TEXT, assumptions_json TEXT, change_note TEXT, model TEXT,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), UNIQUE (run_id, key)
);
CREATE INDEX def_requirement_run ON def_requirement(run_id, key);
CREATE TABLE def_spec (
    id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES checkpoint_run(id), req_key TEXT NOT NULL, version INTEGER NOT NULL,
    parent_id INTEGER REFERENCES def_spec(id), req_version INTEGER, metric_json TEXT, acceptance_json TEXT, ladder_json TEXT,
    gaps_json TEXT, assumptions_json TEXT, fact_ids_json TEXT, input_ids_json TEXT, change_note TEXT, model TEXT,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), UNIQUE (run_id, req_key)
);
CREATE INDEX def_spec_run ON def_spec(run_id, req_key);
CREATE TABLE prio_score (
    id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES checkpoint_run(id), req_key TEXT NOT NULL, req_version INTEGER,
    line TEXT NOT NULL, market TEXT NOT NULL, score REAL NOT NULL, base REAL, band TEXT NOT NULL, rank INTEGER,
    confidence_json TEXT, breakdown_json TEXT, modifiers_json TEXT, flags_json TEXT, bundle_id TEXT, rung TEXT, rationale TEXT,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), UNIQUE (run_id, req_key, line, market)
);
CREATE INDEX prio_score_run ON prio_score(run_id, line, market);
CREATE INDEX prio_score_target ON prio_score(req_key, line, market);
CREATE TABLE prio_decision (   -- append-only: the PM's confirmed priority per requirement × line × market
    id INTEGER PRIMARY KEY, req_key TEXT NOT NULL, line TEXT NOT NULL, market TEXT NOT NULL, priority TEXT NOT NULL,
    rationale TEXT NOT NULL, actor TEXT NOT NULL, checkpoint_id TEXT,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TRIGGER prio_decision_no_update BEFORE UPDATE ON prio_decision BEGIN SELECT RAISE(ABORT, 'prio_decision is append-only'); END;
CREATE TRIGGER prio_decision_no_delete BEFORE DELETE ON prio_decision BEGIN SELECT RAISE(ABORT, 'prio_decision is append-only'); END;
CREATE TABLE def_choice (   -- append-only: the PM's chosen ladder level per requirement × line × market
    id INTEGER PRIMARY KEY, req_key TEXT NOT NULL, line TEXT NOT NULL, market TEXT NOT NULL, level TEXT NOT NULL,
    rationale TEXT NOT NULL, actor TEXT NOT NULL, checkpoint_id TEXT,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TRIGGER def_choice_no_update BEFORE UPDATE ON def_choice BEGIN SELECT RAISE(ABORT, 'def_choice is append-only'); END;
CREATE TRIGGER def_choice_no_delete BEFORE DELETE ON def_choice BEGIN SELECT RAISE(ABORT, 'def_choice is append-only'); END;
CREATE TABLE def_link_review (   -- append-only: the PM confirms, removes or adds a link
    id INTEGER PRIMARY KEY, a_key TEXT NOT NULL, b_key TEXT NOT NULL, relation TEXT NOT NULL, verdict TEXT NOT NULL,
    via TEXT, strength INTEGER, rationale TEXT NOT NULL, actor TEXT NOT NULL, checkpoint_id TEXT,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TRIGGER def_link_review_no_update BEFORE UPDATE ON def_link_review BEGIN SELECT RAISE(ABORT, 'def_link_review is append-only'); END;
CREATE TRIGGER def_link_review_no_delete BEFORE DELETE ON def_link_review BEGIN SELECT RAISE(ABORT, 'def_link_review is append-only'); END;
