// Page 4 overlays at the edges of the shared canvas: car line, market and view switch with the band readout top-left;
// the ranked priorities and the target inspector behind the top-right "Priorities" pill (factor waterfall, gates,
// what-if rung, bundle, flags, history, proposal and the PM's decision); the market × requirement matrix as the 2D
// alternative; the hover card; and the Guide / Agent dock bottom-left. State lives in ./store (market, selection)
// and page 3's store (car line), so the skyline in the canvas and the overlays stay in step.
import { useEffect, useMemo, useRef, useState } from "react";
import { X } from "lucide-react";
import type { Rung } from "@/lib/definition";
import type { Band, Proposal, Target } from "@/lib/prioritize";
import { BANDS, gateResult, gateWhy } from "@/lib/prioritize";
import { Dock } from "@/components/Guide";
import { getActor } from "@/lib/api";
import { getTopPanel, setTopPanel, useTopPanel } from "@/components/topPanel";
import { useCheckpoint } from "@/state/checkpoint";
import { AgentPanel, useActivity } from "../structure/AgentPanel";
import { domainColor } from "../definition/data";
import { setView, useView } from "../definition/store";
import { DEF_STAGES } from "../definition/stages";
import type { LineName } from "@/lib/definition";
import {
  CAUSE_LABEL, CP_LABEL, bandsAt, disagreements, factorLabel, flagLabel, isBlocked, linesOf, marketsOf, openProposals, parseFlags,
  pmBand, shownBand, tid, useDecision, usePrioritize, useProposalVerdict, useTargetDetail, useWhatIf, type PrioData,
} from "./data";
import { Arrow, BandMark, GateMark } from "./marks";
import { Waterfall } from "./Waterfall";
import { PrioritizeGuide } from "./guide";
import { getP, selectTarget, setP, useP } from "./store";
import { WeightsButton, WeightsPanel, setWeightsOpen, useWeightsOpen, weightsNote } from "./weights";
import { useRescoring } from "./rescore";
import { Challenged } from "./challenged";
import { BundleMembers, Deciding } from "./deciding";
import "./prioritize.css";

const fmt = (n: number | undefined | null) => (n == null ? "–" : Math.round(n).toLocaleString("en-US"));
const DOMAIN_LABEL: Record<string, string> = {
  exterior: "Exterior", interior: "Interior & comfort", powertrain: "Powertrain & charging", chassis: "Chassis & dynamics",
  assist: "Driver assistance", digital: "Infotainment & digital", variants: "Variants & packages", quality: "Design & quality",
};
const DOMAIN_ORDER = Object.keys(DOMAIN_LABEL);
const MARKET_NAME: Record<string, string> = { US: "US", EU: "Europe", CN: "China", JP: "Japan", RoW: "Rest of world" };

export function PrioritizeHud() {
  const pd = usePrioritize();
  const { data } = pd;
  const activity = useActivity("prioritize");
  const line = useView((s) => s.line);
  const lines = useMemo(() => linesOf(data), [data]);
  const markets = useMemo(() => marketsOf(data, line), [data, line]);
  const stored = useP((s) => s.market[line]);
  const market = stored && markets.includes(stored) ? stored : markets[0] ?? "";
  const selected = useP((s) => s.selected);
  const view = useP((s) => s.view);
  useP((s) => s.pending);
  useP((s) => s.pendingProposals);

  // page 4 continues on the car: page 3's stage is the car, nothing of page 3 stays open
  useEffect(() => { setView({ stage: DEF_STAGES[DEF_STAGES.length - 1], auto: false, selected: null, hover: null, hoverPos: null, bundle: null }); }, []);
  // a line without prioritized targets falls back to one that has them
  useEffect(() => { if (lines.length && !lines.includes(line)) setView({ line: (lines.includes("5 Series") ? "5 Series" : lines[0]) as LineName }); }, [lines, line]);

/* Track-while-scan: a true-black scan volume, white contacts, one blue for the sweep and the PM's marks,
   amber only for weakened / lost tracks. Numerals carry the information; words are labels, never paragraphs. */
:root {
  color-scheme: dark;

  /* ground */
  --void: #000000;
  --glass: rgba(10, 12, 15, 0.72);
  --hair: rgba(255, 255, 255, 0.09);
  --hair-2: rgba(255, 255, 255, 0.16);
  /* the frameless panel field (inspector, hover card, filter values, audit trail, dock): plain black at 86%, as the
     audit trail had it; no tint, no glow */
  --field: rgba(0, 0, 0, 0.86);

  /* ink */
  --ink: #f2f4f7;
  --ink-2: #b4bac4;
  --ink-3: #868d99;   /* ≥ 4.5:1 on black */

  /* signal */
  --sweep: #1c69d4;
  --sweep-hi: #4d94ff;
  --sweep-wash: rgba(28, 105, 212, 0.18);
  --lost: #f5a524;

  /* type */
  --font: "Mona Sans Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --t-micro: 11px;
  --t-label: 12px;
  --t-body: 14px;
  --t-read: 18px;

  /* space, shape, motion */
  --edge: 24px;
  --r: 10px;
  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  --fast: 160ms;
  --med: 240ms;
  --sweep-ms: 2400ms;   /* matches the 3D sweep in Scene.tsx */
}
/* Page 4, Prioritize: the priority skyline's overlays. Same world as pages 1–3: true black, frameless instruments at
   the 24px edge, numerals lead, domain hues on the marks only, band by SHAPE (Must solid, Should outlined, Could a
   thin line), white = attention, sweep blue only for the PM's confirmed band. Reuses page 3's .dseg / .dlist / .dsheet. */

/* the scan's DOM labels stay gone, as on page 3 */
.scan[data-mode="prioritize"] :is(.ring-name, .ring-sub, .time-label, .ring-label, .theme-label, .area-label) { opacity: 0 !important; pointer-events: none; }
.scan[data-mode="prioritize"] ~ .dock .dock-body, .scan[data-mode="prioritize"] .dock-body { max-height: min(40vh, 340px); }

/* ------------------------------------------------------------------------------------------- band mark */
.pband { display: inline-block; flex: none; position: relative; width: 8px; height: 14px; --c: var(--ink-2); }
.pband[data-band="Must"] { background: var(--c); border-radius: 1px; }
.pband[data-band="Should"] { box-shadow: inset 0 0 0 1.4px var(--c); border-radius: 1px; background: color-mix(in srgb, var(--c) 14%, transparent); height: 11px; margin-top: 3px; }
.pband[data-band="Could"] { width: 8px; background: linear-gradient(var(--c), var(--c)) center 3px / 1.6px calc(100% - 3px) no-repeat; height: 8px; margin-top: 6px; }
.pband[data-band="Could"]::before { content: ""; position: absolute; left: 2px; top: 0; width: 4px; height: 4px; border-radius: 50%; background: var(--c); }
.pband[data-band="none"] { width: 8px; height: 3px; margin-top: 11px; border-radius: 50%; box-shadow: inset 0 0 0 1px var(--ink-3); }
.pband[data-size="sm"] { transform: scale(0.8); transform-origin: bottom center; }
.pband[data-size="lg"] { transform: scale(1.4); transform-origin: bottom center; }
/* the PM's confirmed band: the PM's position, so the one blue mark: a sweep-hi underline with its wash */
.pband[data-pm]::after { content: ""; position: absolute; left: -3px; right: -3px; bottom: -4px; height: 2px; border-radius: 1px; background: var(--sweep-hi); box-shadow: 0 0 0 2px var(--sweep-wash); }

.pgate { width: 10px; height: 10px; border-radius: 50%; flex: none; position: relative; display: inline-block; }
.pgate[data-r="pass"] { background: var(--ink-2); }
.pgate[data-r="warn"] { box-shadow: inset 0 0 0 1.4px var(--ink); background: linear-gradient(90deg, var(--ink) 50%, transparent 50%); }
.pgate[data-r="fail"] { box-shadow: inset 0 0 0 1.4px var(--ink); }
.pgate[data-r="fail"]::after { content: ""; position: absolute; left: 4.3px; top: 0.5px; width: 1.4px; height: 9px; background: var(--ink); transform: rotate(45deg); }
.pgate[data-r="unchecked"] { box-shadow: inset 0 0 0 1px var(--ink-3); }
.parrow { font-size: 8px; margin-left: 4px; color: var(--ink); vertical-align: 1px; }
.parrow[data-d="down"] { color: var(--ink-3); }

